// ─── Language ───────────────────────────────────────────────────────────────
let currentLang = localStorage.getItem('sf_lang') || 'en';

function setLang(lang) {
  currentLang = lang;
  localStorage.setItem('sf_lang', lang);
  const d = TRANSLATIONS[lang];
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const k = el.getAttribute('data-i18n');
    if (d[k] !== undefined) el.innerHTML = d[k];
  });
  document.querySelectorAll('[data-i18n-ph]').forEach(el => {
    const k = el.getAttribute('data-i18n-ph');
    if (d[k] !== undefined) el.placeholder = d[k];
  });
  // Select options
  document.querySelectorAll('select option[data-i18n]').forEach(el => {
    const k = el.getAttribute('data-i18n');
    if (d[k] !== undefined) el.textContent = d[k];
  });
  document.querySelectorAll('.lang-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.lang === lang);
  });
  document.documentElement.setAttribute('lang', lang);
}

document.querySelectorAll('.lang-btn').forEach(btn => {
  btn.addEventListener('click', () => setLang(btn.dataset.lang));
});
setLang(currentLang);

// ─── Theme toggle ────────────────────────────────────────────────────────────
// ─── Nav scroll effect ────────────────────────────────────────────────────────
const nav = document.querySelector('.nav');
window.addEventListener('scroll', () => {
  nav.classList.toggle('scrolled', window.scrollY > 40);
}, {passive:true});

// ─── Mobile menu ─────────────────────────────────────────────────────────────
const hamburger = document.getElementById('hamburger');
const mobileMenu = document.getElementById('mobMenu');

function closeMob() {
  if (mobileMenu) mobileMenu.classList.remove('open');
  if (hamburger) hamburger.setAttribute('aria-expanded', 'false');
  document.body.style.overflow = '';
}

if (hamburger && mobileMenu) {
  hamburger.addEventListener('click', () => {
    const open = mobileMenu.classList.toggle('open');
    hamburger.setAttribute('aria-expanded', open);
    document.body.style.overflow = open ? 'hidden' : '';
  });
}

// ─── Fade-up observer ─────────────────────────────────────────────────────────
const io = new IntersectionObserver(entries => {
  entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('visible','vis'); io.unobserve(e.target); } });
}, {threshold:0.05});
document.querySelectorAll('.fade-up,.fu').forEach(el => io.observe(el));

// ─── Stat counters ────────────────────────────────────────────────────────────
function animateCount(el) {
  const target = +el.dataset.count;
  const suffix = el.dataset.suffix || '';
  const dur = 1600;
  const start = performance.now();
  function step(now) {
    const p = Math.min((now - start) / dur, 1);
    const ease = 1 - Math.pow(1 - p, 3);
    el.textContent = Math.round(ease * target) + suffix;
    if (p < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}
const statsObs = new IntersectionObserver(entries => {
  entries.forEach(e => {
    if (e.isIntersecting) { animateCount(e.target); statsObs.unobserve(e.target); }
  });
}, {threshold:0.5});
document.querySelectorAll('.stat-num').forEach(el => statsObs.observe(el));

// ─── FAQ accordion ────────────────────────────────────────────────────────────
document.querySelectorAll('.faq-q').forEach(btn => {
  btn.addEventListener('click', () => {
    const item = btn.closest('.faq-item');
    const wasOpen = item.classList.contains('open');
    document.querySelectorAll('.faq-item.open').forEach(i => i.classList.remove('open'));
    if (!wasOpen) item.classList.add('open');
  });
});

// ─── Contact form ─────────────────────────────────────────────────────────────
document.getElementById('contactForm').addEventListener('submit', e => {
  e.preventDefault();
  const form = e.target;
  const btn = form.querySelector('.form-submit');
  btn.disabled = true;
  btn.style.opacity = '.6';
  setTimeout(() => {
    form.reset();
    document.getElementById('formSuccess').style.display = 'block';
    btn.disabled = false;
    btn.style.opacity = '1';
    setTimeout(() => { document.getElementById('formSuccess').style.display = 'none'; }, 5000);
  }, 800);
});

// ─── Smooth scroll for anchor links ──────────────────────────────────────────
document.querySelectorAll('a[href^="#"]').forEach(a => {
  a.addEventListener('click', e => {
    const target = document.querySelector(a.getAttribute('href'));
    if (target) { e.preventDefault(); target.scrollIntoView({behavior:'smooth', block:'start'}); }
  });
});

/* ── CONFIGURATOR LOGIC ── */
(function(){
  const BASE_PRICES = {sosna:65000, kedr:98000, listv:155000};
  let state = {model:'kedr', timber:'cedar', roof:'classic', glaz:'std', delivery:'ass'};
  let costs = {timber:4000, roof:0, glaz:0, delivery:18000};

  function calcPrice(){
    return BASE_PRICES[state.model] + costs.timber + costs.roof + costs.glaz + costs.delivery;
  }

  function updateDisplay(){
    // price
    const p = calcPrice();
    const el = document.getElementById('conf-price');
    if(el) el.textContent = '€' + p.toLocaleString('en');

    // model visual
    document.querySelectorAll('.conf-model-svg').forEach(s=>s.classList.remove('active'));
    const activeCard = document.querySelector('.conf-model-card.selected');
    if(activeCard){
      const svgId = 'svg-'+activeCard.dataset.model;
      const svg = document.getElementById(svgId);
      if(svg) svg.classList.add('active');
      // update label
      const lang = document.documentElement.lang || 'en';
      const sizeKey = 'data-size-'+lang;
      const mn = document.getElementById('conf-model-name');
      const ms = document.getElementById('conf-model-size');
      if(mn) mn.textContent = activeCard.dataset.name;
      if(ms) ms.textContent = activeCard.getAttribute(sizeKey) || activeCard.getAttribute('data-size-en') || '';
    }

    // group value labels
    const tv = document.getElementById('conf-val-timber');
    if(tv){
      const ts = document.querySelector('.conf-swatch.selected .conf-swatch-label');
      if(ts) tv.textContent = ts.textContent;
    }
    const rv = document.getElementById('conf-val-roof');
    if(rv){
      const rs = document.querySelector('.conf-radio-item.selected[data-roof] .conf-ri-label');
      if(rs) rv.textContent = rs.textContent;
    }
    const gv = document.getElementById('conf-val-glaz');
    if(gv){
      const gs = document.querySelector('.conf-toggle-btn.selected');
      if(gs) gv.textContent = gs.textContent.replace(/\s*\+.*$/,'').trim();
    }
    const dv = document.getElementById('conf-val-delivery');
    if(dv){
      const ds = document.querySelector('.conf-radio-item.selected[data-delivery] .conf-ri-label');
      if(ds) dv.textContent = ds.textContent;
    }
    const mv = document.getElementById('conf-val-model');
    if(mv && activeCard) mv.textContent = activeCard.dataset.name;
  }

  // Model cards
  document.querySelectorAll('.conf-model-card').forEach(btn=>{
    btn.addEventListener('click',()=>{
      document.querySelectorAll('.conf-model-card').forEach(b=>b.classList.remove('selected'));
      btn.classList.add('selected');
      state.model = btn.dataset.model;
      updateDisplay();
    });
  });

  // Timber swatches
  document.querySelectorAll('.conf-swatch').forEach(btn=>{
    btn.addEventListener('click',()=>{
      document.querySelectorAll('.conf-swatch').forEach(b=>b.classList.remove('selected'));
      btn.classList.add('selected');
      state.timber = btn.dataset.timber;
      costs.timber = parseInt(btn.dataset.cost)||0;
      updateDisplay();
    });
  });

  // Roof
  document.querySelectorAll('.conf-radio-item[data-roof]').forEach(btn=>{
    btn.addEventListener('click',()=>{
      document.querySelectorAll('.conf-radio-item[data-roof]').forEach(b=>b.classList.remove('selected'));
      btn.classList.add('selected');
      state.roof = btn.dataset.roof;
      costs.roof = parseInt(btn.dataset.cost)||0;
      updateDisplay();
    });
  });

  // Glazing
  document.querySelectorAll('.conf-toggle-btn').forEach(btn=>{
    btn.addEventListener('click',()=>{
      document.querySelectorAll('.conf-toggle-btn').forEach(b=>b.classList.remove('selected'));
      btn.classList.add('selected');
      state.glaz = btn.dataset.glaz;
      costs.glaz = parseInt(btn.dataset.cost)||0;
      updateDisplay();
    });
  });

  // Delivery
  document.querySelectorAll('.conf-radio-item[data-delivery]').forEach(btn=>{
    btn.addEventListener('click',()=>{
      document.querySelectorAll('.conf-radio-item[data-delivery]').forEach(b=>b.classList.remove('selected'));
      btn.classList.add('selected');
      state.delivery = btn.dataset.delivery;
      costs.delivery = parseInt(btn.dataset.cost)||0;
      updateDisplay();
    });
  });

  // Update model size labels when language changes
  const origApplyLang = window.applyLang;
  window.applyLang = function(lang){
    if(origApplyLang) origApplyLang(lang);
    // re-sync size label after lang switch
    setTimeout(updateDisplay, 50);
  };

  updateDisplay();
})();


/* ── Configurator logic ── */
(function(){
  var BASE_PRICES = { s: 49000, m: 86000, l: 138000 };
  var currentModel = 's';
  var selections = { roof: 0, clad: 0, glaz: 0 };
  var terraces = 0;

  function formatPrice(n){
    return n.toLocaleString('de-DE').replace(/\./g,' ') + ' €';
  }

  function updatePrice(){
    var total = BASE_PRICES[currentModel];
    for(var k in selections) total += selections[k];
    total += terraces * 1800;
    var el = document.getElementById('conf-price');
    if(el) el.textContent = formatPrice(total);
  }

  function updateSpecs(model){
    var specs = {
      s: { area:'40 m²', rooms:'2+1', floors:'1 floor' },
      m: { area:'72 m²', rooms:'3+1', floors:'2 floors' },
      l: { area:'120 m²', rooms:'4+2', floors:'3 floors' }
    };
    var s = specs[model];
    var ea = document.getElementById('spec-area');
    var er = document.getElementById('spec-rooms');
    var ef = document.getElementById('spec-floors');
    if(ea) ea.textContent = s.area;
    if(er) er.textContent = s.rooms;
  }

  // Model switcher
  document.querySelectorAll('.conf-model-btn').forEach(function(btn){
    btn.addEventListener('click', function(){
      document.querySelectorAll('.conf-model-btn').forEach(function(b){ b.classList.remove('active'); });
      btn.classList.add('active');
      currentModel = btn.dataset.model;
      ['s','m','l'].forEach(function(id){
        var svg = document.getElementById('svg-'+id);
        if(svg) svg.style.display = (id === currentModel) ? '' : 'none';
      });
      updateSpecs(currentModel);
      updatePrice();
    });
  });

  // Option selectors
  document.querySelectorAll('.conf-option').forEach(function(opt){
    opt.addEventListener('click', function(){
      var group = opt.dataset.opt;
      document.querySelectorAll('[data-opt="'+group+'"]').forEach(function(o){ o.classList.remove('selected'); });
      opt.classList.add('selected');
      selections[group] = parseInt(opt.dataset.price)||0;
      updatePrice();
    });
  });

  // Terrace stepper
  var tminus = document.getElementById('terrace-minus');
  var tplus  = document.getElementById('terrace-plus');
  var tval   = document.getElementById('terrace-val');
  if(tplus) tplus.addEventListener('click', function(){
    terraces = Math.min(terraces+1, 4);
    if(tval) tval.textContent = terraces;
    updatePrice();
  });
  if(tminus) tminus.addEventListener('click', function(){
    terraces = Math.max(terraces-1, 0);
    if(tval) tval.textContent = terraces;
    updatePrice();
  });

  updatePrice();
})();


/* ── Models Slider ── */
(function(){
  var track = document.getElementById('ms-track');
  var prev = document.getElementById('ms-prev');
  var next = document.getElementById('ms-next');
  var cur = document.getElementById('ms-cur');
  var total = document.getElementById('ms-total');
  var dots = document.querySelectorAll('.ms-dot');
  if(!track) return;

  var idx = 0;
  var count = track.children.length;
  if(total) total.textContent = count;

  function goTo(n){
    idx = Math.max(0, Math.min(n, count-1));
    track.style.transform = 'translateX(-' + (idx * 100) + '%)';
    if(cur) cur.textContent = idx + 1;
    dots.forEach(function(d,i){ d.classList.toggle('active', i===idx); });
    if(prev) prev.disabled = idx === 0;
    if(next) next.disabled = idx === count - 1;
  }

  if(prev) prev.addEventListener('click', function(){ goTo(idx-1); });
  if(next) next.addEventListener('click', function(){ goTo(idx+1); });
  dots.forEach(function(d){ d.addEventListener('click', function(){ goTo(+d.dataset.idx); }); });

  // Touch/swipe support
  var startX = 0;
  track.addEventListener('touchstart', function(e){ startX = e.touches[0].clientX; }, {passive:true});
  track.addEventListener('touchend', function(e){
    var dx = e.changedTouches[0].clientX - startX;
    if(Math.abs(dx) > 50) goTo(dx < 0 ? idx+1 : idx-1);
  }, {passive:true});

  goTo(0);
})();




