(function(){
  var LEFT_DESCS = {
    en: [
      'Certified Siberian larch, precision-cut at our own factory. Every element arrives numbered and ready to assemble.',
      'CNC-machined to ±0.5 mm tolerance. Each panel, beam and connector is part of a numbered kit.',
      'A crew of four erects Sosna S in 7 days. No heavy machinery — just the kit and the manual.',
      '200 mm insulation keeps the interior warm even at −35 °C. Live here all year.'
    ],
    ro: [
      'Larice siberian certificat, tăiat cu precizie la fabrica noastră. Fiecare element vine numerotat și gata de asamblat.',
      'Tăiat CNC la toleranță ±0,5 mm. Fiecare panou, grindă și conector face parte dintr-un kit numerotat.',
      'O echipă de patru persoane ridică Sosna S în 7 zile. Fără utilaje grele — doar kitul și manualul.',
      '200 mm izolație menține interiorul cald chiar și la −35 °C. Locuiți aici tot anul.'
    ],
    pl: [
      'Certyfikowana syberyska modrzew, precyzyjnie cięta w naszej fabryce. Każdy element dostarczamy ponumerowany i gotowy do montażu.',
      'Obróbka CNC z tolerancją ±0,5 mm. Każdy panel, belka i łącznik to część numerowanego zestawu.',
      'Czteroosobowa ekipa wznosi Sosna S w 7 dni. Bez ciężkiego sprzętu — tylko zestaw i instrukcja.',
      '200 mm izolacji utrzymuje wnętrze ciepłe nawet przy −35 °C. Mieszkaj tu przez cały rok.'
    ]
  };

  function featLang(){
    var btn = document.querySelector('[data-lang].active, .lang-btn.active');
    if(btn && btn.getAttribute('data-lang')) return btn.getAttribute('data-lang');
    return document.documentElement.getAttribute('lang') || 'en';
  }

  function featInit(){
    var scroll = document.getElementById('feat-scroll');
    var curNum = document.getElementById('feat-cur-num');
    var descEl = document.getElementById('feat-left-desc');
    var line   = document.getElementById('feat-progress-line');
    var prev   = document.getElementById('feat-prev');
    var next   = document.getElementById('feat-next');
    if(!scroll) return;

    var cards  = scroll.querySelectorAll('.feat-card');
    var total  = cards.length;
    var cardW  = 0;
    var gap    = 20;
    var curIdx = 0;

    function getCardW(){ return cards[0] ? cards[0].offsetWidth : 300; }

    function updateCounter(idx){
      curIdx = idx;
      var n = idx + 1;
      if(curNum) curNum.textContent = (n < 10 ? '0' : '') + n;
      if(line){
        var pct = (n / total) * 100;
        line.style.setProperty('--feat-prog', pct + '%');
      }
      /* Update left description */
      if(descEl){
        var lang = featLang();
        var descs = LEFT_DESCS[lang] || LEFT_DESCS['en'];
        descEl.textContent = descs[idx] || descs[0];
      }
      if(prev) prev.disabled = idx === 0;
      if(next) next.disabled = idx === total - 1;
    }

    function scrollTo(idx){
      cardW = getCardW();
      scroll.scrollTo({ left: idx * (cardW + gap), behavior: 'smooth' });
      updateCounter(idx);
    }

    if(prev) prev.addEventListener('click', function(){ scrollTo(Math.max(0, curIdx - 1)); });
    if(next) next.addEventListener('click', function(){ scrollTo(Math.min(total - 1, curIdx + 1)); });

    /* Update counter on scroll */
    scroll.addEventListener('scroll', function(){
      cardW = getCardW();
      var idx = Math.round(scroll.scrollLeft / (cardW + gap));
      if(idx !== curIdx) updateCounter(Math.max(0, Math.min(idx, total - 1)));
    }, { passive: true });

    /* Dynamic progress line */
    var styleEl = document.createElement('style');
    styleEl.textContent = '#feat-progress-line::after{width:var(--feat-prog,0%)!important}';
    document.head.appendChild(styleEl);

    /* Re-render on language change */
    document.addEventListener('click', function(e){
      var t = e.target;
      if(t && (t.getAttribute('data-lang') || (t.closest && t.closest('[data-lang]')))){
        setTimeout(function(){ updateCounter(curIdx); }, 60);
      }
    }, true);

    updateCounter(0);
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', featInit);
  } else {
    featInit();
  }
})();


