(function() {
  'use strict';
  var video = document.getElementById('hero-video');
  var isMobile = window.innerWidth <= 768;

  /* Fade video in once it has enough data */
  if (video) {
    video.style.opacity = '0';
    function showVideo() { video.style.opacity = '1'; }
    if (video.readyState >= 3) { showVideo(); }
    else {
      video.addEventListener('canplay', showVideo, { once: true });
      video.addEventListener('loadeddata', showVideo, { once: true });
    }
  }

  /* ── MOBILE: autoplay loop, show content immediately ── */
  if (isMobile) {
    if (video) {
      video.loop = true;
      video.muted = true;
      video.play().catch(function(){});
      /* iOS fallback: play on first touch if autoplay blocked */
      document.addEventListener('touchstart', function() {
        if (video.paused) video.play().catch(function(){});
      }, { once: true });
    }
    /* Hero content visible immediately */
    var bottomBar = document.querySelector('.hero-bottom-bar');
    if (bottomBar) bottomBar.style.opacity = '1';
    return; /* skip scroll animation */
  }

  /* ── DESKTOP: scroll-driven scrubbing ── */
  var wrapperTop = 0, wrapperScrollable = 1;

  function cacheWrapper() {
    var wr = document.getElementById('hero-scroll-wrapper');
    if (!wr) return;
    var rect = wr.getBoundingClientRect();
    var scrollY = window.pageYOffset || document.documentElement.scrollTop || 0;
    wrapperTop = rect.top + scrollY;
    wrapperScrollable = Math.max(1, wr.offsetHeight - window.innerHeight);
  }

  function getProgress() {
    var scrollY = window.pageYOffset || document.documentElement.scrollTop || 0;
    return Math.max(0, Math.min(1, (scrollY - wrapperTop) / wrapperScrollable));
  }

  function fadeAt(p, start, range) {
    return Math.max(0, Math.min(1, (p - start) / range));
  }

  var lastScrollY = -1;
  function loop() {
    var scrollY = window.pageYOffset || document.documentElement.scrollTop || 0;
    if (scrollY !== lastScrollY) {
      lastScrollY = scrollY;
      var p = getProgress();
      if (video && video.readyState >= 2 && video.duration) {
        video.currentTime = p * video.duration;
      }
      var brandCenter = document.querySelector('.hero-brand-center');
      var bottomBar   = document.querySelector('.hero-bottom-bar');
      if (brandCenter) brandCenter.style.opacity = fadeAt(p, 0.15, 0.18);
      if (bottomBar)   bottomBar.style.opacity   = fadeAt(p, 0.38, 0.22);
    }
    requestAnimationFrame(loop);
  }

  window.addEventListener('resize', cacheWrapper);

  function init() {
    var wr = document.getElementById('hero-scroll-wrapper');
    if (wr) wr.style.height = '550vh';
    cacheWrapper();
    requestAnimationFrame(loop);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else { init(); }
}());


