/* ── NAV SCROLL SPY ── */
(function(){
  var sections = ['home','models','services','delivery','process','reviews','faq','contact'];
  var navLinks = document.querySelectorAll('.nav-pill a');
  
  function setActive(id) {
    navLinks.forEach(function(a){
      var href = a.getAttribute('href');
      if(href === '#' + id) {
        a.classList.add('active');
      } else {
        a.classList.remove('active');
      }
    });
  }
  
  // Set initial active based on scroll position
  function onScroll() {
    var scrollY = window.pageYOffset || document.documentElement.scrollTop;
    var winH = window.innerHeight;
    var active = sections[0];
    
    for(var i = 0; i < sections.length; i++) {
      var el = document.getElementById(sections[i]);
      if(!el) continue;
      var rect = el.getBoundingClientRect();
      if(rect.top <= winH * 0.5) {
        active = sections[i];
      }
    }
    setActive(active);
  }
  
  // Also update active on click
  navLinks.forEach(function(a){
    a.addEventListener('click', function(){
      var href = this.getAttribute('href').replace('#','');
      setActive(href);
    });
  });
  
  window.addEventListener('scroll', onScroll, {passive: true});
  onScroll(); // run on load
})();


