/* ═══════ SF ANIMATIONS v1 ═══════ */
(function(){
'use strict';

/* ── 1. Intersection Observer for reveal ── */
const revealObs = new IntersectionObserver((entries) => {
  entries.forEach(e => {
    if (e.isIntersecting) {
      e.target.classList.add('sf-visible');
      revealObs.unobserve(e.target);
    }
  });
}, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });

function addReveal(el, cls, delay) {
  el.classList.add(cls || 'sf-reveal');
  if (delay) el.classList.add('sf-d' + delay);
  revealObs.observe(el);
}

/* ── 2. Tag elements for reveal ── */
function initReveal() {
  /* About editorial */
  const aboutText = document.querySelector('.about-editorial [style*="padding:80px"]');
  if (aboutText) addReveal(aboutText, 'sf-reveal-left');

  const aboutImg = document.querySelector('.about-editorial img');
  if (aboutImg) addReveal(aboutImg, 'sf-reveal-scale', 2);

  /* Portfolio grid items */
  document.querySelectorAll('.portf-item, .portf-card, .portf-grid > *').forEach((el, i) => {
    addReveal(el, 'sf-reveal-scale', Math.min(i + 1, 6));
  });

  /* Models section */
  const mcHeader = document.querySelector('.mc-header');
  if (mcHeader) addReveal(mcHeader, 'sf-reveal');

  const mcLeft = document.querySelector('.mc-left');
  if (mcLeft) addReveal(mcLeft, 'sf-reveal-left');

  const mcRight = document.querySelector('.mc-right');
  if (mcRight) addReveal(mcRight, 'sf-reveal-right');

  /* Features / feat cards */
  document.querySelectorAll('.feat-card, .feat-item, .feat-sec .sec-body > *').forEach((el, i) => {
    addReveal(el, 'sf-reveal', Math.min(i + 1, 5));
  });

  /* Process steps */
  document.querySelectorAll('.proc-step').forEach((el, i) => {
    addReveal(el, 'sf-reveal', Math.min(i + 1, 6));
  });

  /* Reviews */
  document.querySelectorAll('.rev-card').forEach((el, i) => {
    addReveal(el, 'sf-reveal-scale', Math.min(i + 1, 4));
  });

  /* FAQ */
  document.querySelectorAll('.faq2-item, .faq2-bar').forEach((el, i) => {
    addReveal(el, 'sf-reveal', Math.min(i + 1, 5));
  });

  /* Section headings */
  document.querySelectorAll('.portf-inner > *, .mc-header > *').forEach((el, i) => {
    if (!el.classList.contains('sf-reveal')) addReveal(el, 'sf-reveal', i + 1);
  });

  /* Delivery editorial */
  const delivText = document.querySelector('.deliv-editorial');
  if (delivText) addReveal(delivText, 'sf-reveal');
}

/* ── 3. Parallax on RAF ── */
let ticking = false;
const parallaxEls = [];

function gatherParallax() {
  /* Hero background */
  const heroBg = document.querySelector('.hero-bg-photo');
  if (heroBg) parallaxEls.push({ el: heroBg, speed: 0.35, type: 'hero' });

  /* About editorial image */
  const aboutImg = document.querySelector('.about-editorial img');
  if (aboutImg) parallaxEls.push({ el: aboutImg, speed: 0.18, type: 'scroll' });

  /* Portfolio images */
  document.querySelectorAll('.portf-item img, .portf-card img').forEach(img => {
    parallaxEls.push({ el: img, speed: 0.12, type: 'scroll' });
  });
}

function updateParallax() {
  const scrollY = window.scrollY;

  parallaxEls.forEach(({ el, speed, type }) => {
    if (type === 'hero') {
      // Hero bg: translates up as user scrolls down
      const offset = scrollY * speed;
      el.style.transform = 'translateY(' + offset + 'px) scale(1.08)';
    } else {
      // Section parallax: translate relative to element's position
      const rect = el.closest('section')
        ? el.closest('section').getBoundingClientRect()
        : el.getBoundingClientRect();
      const winH = window.innerHeight;
      if (rect.bottom < -winH || rect.top > winH * 2) return;
      const center = rect.top + rect.height / 2 - winH / 2;
      el.style.transform = 'translateY(' + (center * -speed) + 'px) scale(1.12)';
    }
  });
  ticking = false;
}

function onScroll() {
  if (!ticking) {
    requestAnimationFrame(updateParallax);
    ticking = true;
  }
}

/* ── 4. Smooth counter for hero stat ── */
function animateCounter(el, target, duration) {
  const start = performance.now();
  const step = (now) => {
    const t = Math.min((now - start) / duration, 1);
    const ease = 1 - Math.pow(1 - t, 3);
    el.textContent = Math.round(ease * target);
    if (t < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

function initCounters() {
  document.querySelectorAll('.hsr-num, .stat-num').forEach(el => {
    const text = el.textContent.trim();
    const num = parseInt(text.replace(/[^0-9]/g, ''));
    if (!num || num < 10) return;
    const suffix = text.replace(/[0-9]/g, '');
    const obs = new IntersectionObserver(entries => {
      entries.forEach(e => {
        if (e.isIntersecting) {
          animateCounter({ textContent: '', set textContent(v) { el.textContent = v + suffix; } }, num, 1400);
          obs.unobserve(el);
        }
      });
    }, { threshold: 0.5 });
    obs.observe(el);
  });
}

/* ── 5. Image scale on hover for portf ── */
function initHoverEffects() {
  document.querySelectorAll('.portf-item, .portf-card').forEach(card => {
    const img = card.querySelector('img');
    if (!img) return;
    img.style.transition = 'transform .7s cubic-bezier(.16,1,.3,1)';
    card.addEventListener('mouseenter', () => {
      img.style.transform = img.style.transform.replace(/scale\([^)]*\)/, '') + ' scale(1.07)';
    });
    card.addEventListener('mouseleave', () => {
      img.style.transform = img.style.transform.replace(/scale\([^)]*\)/, '');
    });
  });
}

/* ── Init on DOM ready ── */
function init() {
  initReveal();
  gatherParallax();
  initCounters();
  initHoverEffects();
  window.addEventListener('scroll', onScroll, { passive: true });
  updateParallax(); // initial call
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}

})();


