(function(){
  var abCurrent = 0;
  var abTotal = 4;
  function abUpdate(idx){
    var slides = document.querySelectorAll('.ab-slide');
    var dots   = document.querySelectorAll('.ab-dot');
    slides.forEach(function(s,i){
      s.classList.toggle('ab-slide-active', i===idx);
    });
    dots.forEach(function(d,i){
      d.classList.toggle('ab-dot-active', i===idx);
    });
    abCurrent = idx;
  }
  window.abSlide = function(dir){
    abUpdate((abCurrent + dir + abTotal) % abTotal);
  };
  window.abGoTo = function(idx){ abUpdate(idx); };

  // Touch / drag support
  var startX = 0;
  var carousel = document.querySelector('.ab-carousel');
  if(carousel){
    carousel.addEventListener('touchstart', function(e){ startX = e.touches[0].clientX; }, {passive:true});
    carousel.addEventListener('touchend', function(e){
      var dx = e.changedTouches[0].clientX - startX;
      if(Math.abs(dx) > 40) abSlide(dx < 0 ? 1 : -1);
    }, {passive:true});
  }
})();


