(function() {
  // --- Scroll reveal ---
  function addAnimClasses() {
    // Hero elements
    var heroTitle = document.querySelector('.hero-title');
    var heroSub = document.querySelector('.hero-subtitle, .hero-desc');
    var heroCta = document.querySelector('.hero-cta, .hero-btns');
    if (heroTitle) heroTitle.classList.add('anim-fade');
    if (heroSub) { heroSub.classList.add('anim-fade', 'anim-d2'); }
    if (heroCta) { heroCta.classList.add('anim-fade', 'anim-d3'); }

    // Section headings
    document.querySelectorAll('.section-label, .sec-label, .eyebrow').forEach(function(el) {
      el.classList.add('anim-fade');
    });
    document.querySelectorAll('h2, h3').forEach(function(el) {
      if (!el.closest('.hero') && !el.closest('nav')) el.classList.add('anim-fade');
    });

    // Feature/spec cards
    document.querySelectorAll('.spec-card, .feat-card, .feature-card, .info-card').forEach(function(el, i) {
      el.classList.add('anim-fade');
      if (i % 3 === 1) el.classList.add('anim-d2');
      if (i % 3 === 2) el.classList.add('anim-d3');
    });

    // Review cards
    document.querySelectorAll('.rev-card, .review-card, .testimonial-card').forEach(function(el, i) {
      el.classList.add('anim-scale');
      if (i % 4 === 1) el.classList.add('anim-d1');
      if (i % 4 === 2) el.classList.add('anim-d2');
      if (i % 4 === 3) el.classList.add('anim-d3');
    });

    // Configurator sides
    var mcLeft = document.querySelector('.mc-left');
    var mcRight = document.querySelector('.mc-right');
    if (mcLeft) mcLeft.classList.add('anim-fade-left');
    if (mcRight) mcRight.classList.add('anim-fade-right');

    // Contact section
    var cont3Photo = document.querySelector('.cont3-photo');
    var cont3Content = document.querySelector('.cont3-content');
    if (cont3Photo) cont3Photo.classList.add('anim-fade-left');
    if (cont3Content) cont3Content.classList.add('anim-fade-right');

    // FAQ items
    document.querySelectorAll('.faq-item').forEach(function(el, i) {
      el.classList.add('anim-fade');
      if (i % 4 === 1) el.classList.add('anim-d1');
      if (i % 4 === 2) el.classList.add('anim-d2');
      if (i % 4 === 3) el.classList.add('anim-d3');
    });

    // Stats / numbers
    document.querySelectorAll('.stat-item, .number-item, .count-item').forEach(function(el, i) {
      el.classList.add('anim-fade');
      el.classList.add('anim-d' + Math.min(i + 1, 6));
    });

    // Gallery images
    document.querySelectorAll('.gallery-item, .gal-item, .img-card').forEach(function(el, i) {
      el.classList.add('anim-scale');
      if (i % 3 === 1) el.classList.add('anim-d1');
      if (i % 3 === 2) el.classList.add('anim-d2');
    });

    // Process / steps
    document.querySelectorAll('.step-item, .process-step, .timeline-item').forEach(function(el, i) {
      el.classList.add('anim-fade');
      if (i % 3 === 1) el.classList.add('anim-d2');
      if (i % 3 === 2) el.classList.add('anim-d3');
    });

    // Paragraphs inside sections (not hero)
    document.querySelectorAll('section p, .section p').forEach(function(el) {
      if (!el.closest('.hero') && !el.classList.contains('anim-fade')) el.classList.add('anim-fade', 'anim-d1');
    });
  }

  // Intersection observer for reveal
  function initReveal() {
    var observer = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });

    document.querySelectorAll('.anim-fade, .anim-fade-left, .anim-fade-right, .anim-scale').forEach(function(el) {
      observer.observe(el);
    });
  }

  // --- Parallax on hero bg and section images ---
  function initParallax() {
    var heroImg = document.querySelector('.hero-bg, .hero-img, .hero-media, .hero-image');
    var sections = document.querySelectorAll('.parallax-img');

    function onScroll() {
      var scrollY = window.pageYOffset;

      // Hero parallax
      if (heroImg) {
        heroImg.style.transform = 'translateY(' + (scrollY * 0.35) + 'px)';
      }

      // Also try bg-image divs in hero
      var heroBg = document.querySelector('.hero [style*="background-image"], .hero-bg-wrap');
      if (heroBg && !heroImg) {
        heroBg.style.transform = 'translateY(' + (scrollY * 0.3) + 'px)';
      }

      // Section parallax images
      sections.forEach(function(el) {
        var rect = el.closest('.parallax-wrap') ? el.closest('.parallax-wrap').getBoundingClientRect() : el.getBoundingClientRect();
        var centerY = rect.top + rect.height / 2;
        var viewH = window.innerHeight;
        var offset = (centerY - viewH / 2) * 0.18;
        el.style.transform = 'translateY(' + offset + 'px) scale(1.1)';
      });
    }

    // Add parallax-wrap/img to known image sections
    var contPhotoImg = document.querySelector('.cont3-photo img');
    if (contPhotoImg) {
      contPhotoImg.closest('.cont3-photo').classList.add('parallax-wrap');
      contPhotoImg.classList.add('parallax-img');
    }

    var mcImg = document.querySelector('.mc-img');
    if (mcImg) {
      var mcLeft = mcImg.closest('.mc-left');
      if (mcLeft) { mcLeft.classList.add('parallax-wrap'); mcImg.classList.add('parallax-img'); }
    }

    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
  }

  function init() {
    addAnimClasses();
    initReveal();
    initParallax();

    // Immediately show above-the-fold elements
    setTimeout(function() {
      document.querySelectorAll('.hero .anim-fade, .hero .anim-fade-left, .hero .anim-fade-right, .hero .anim-scale, nav .anim-fade').forEach(function(el) {
        el.classList.add('visible');
      });
    }, 100);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
